import { mysqlTable, index, primaryKey, int, timestamp, varchar, text, decimal, unique, mysqlEnum, tinyint } from "drizzle-orm/mysql-core";
import { sql } from "drizzle-orm";
export const auditLogs = mysqlTable("audit_logs", {
    id: int().autoincrement().notNull(),
    tenantId: int("tenant_id").notNull(),
    createdAt: timestamp("created_at", { mode: 'string' }).default(sql `(now())`).notNull(),
    actorUserId: int("actor_user_id"),
    actorVendedorId: int("actor_vendedor_id"),
    action: varchar({ length: 32 }).notNull(),
    entity: varchar({ length: 64 }).notNull(),
    entityId: varchar("entity_id", { length: 64 }),
    payloadJson: text("payload_json"),
    traceId: varchar("trace_id", { length: 32 }),
    ip: varchar({ length: 45 }),
    userAgent: text("user_agent"),
    severity: varchar({ length: 10 }).default('INFO').notNull(),
    source: varchar({ length: 20 }).default('api').notNull(),
}, (table) => [
    index("audit_created_at_idx").on(table.createdAt),
    index("audit_entity_id_idx").on(table.entityId),
    index("audit_entity_idx").on(table.entity),
    index("audit_ip_idx").on(table.ip),
    primaryKey({ columns: [table.id], name: "audit_logs_id" }),
]);
export const boletos = mysqlTable("boletos", {
    id: int().autoincrement().notNull(),
    tenantId: int("tenant_id").notNull(),
    pedidoId: int("pedido_id").notNull().references(() => pedidos.id),
    clienteId: int("cliente_id").notNull().references(() => clientes.id),
    vendedorId: int("vendedor_id").notNull().references(() => vendedores.id),
    numeroPedido: int("numero_pedido").notNull(),
    valorOriginal: decimal("valor_original", { precision: 10, scale: 2 }).notNull(),
    valorAberto: decimal("valor_aberto", { precision: 10, scale: 2 }).notNull(),
    dataVencimento: timestamp("data_vencimento", { mode: 'string' }).notNull(),
    status: varchar({ length: 50 }).notNull(),
    codigoBarras: varchar("codigo_barras", { length: 100 }),
    pixCopiaECola: text("pix_copia_e_cola"),
    createdAt: timestamp("created_at", { mode: 'string' }).default(sql `(now())`).notNull(),
    updatedAt: timestamp("updated_at", { mode: 'string' }).default(sql `(now())`).onUpdateNow().notNull(),
}, (table) => [
    index("boletos_cliente_idx").on(table.clienteId),
    index("boletos_status_idx").on(table.status),
    index("boletos_tenant_id_idx").on(table.tenantId),
    index("boletos_vencimento_idx").on(table.dataVencimento),
    primaryKey({ columns: [table.id], name: "boletos_id" }),
]);
