    telefoneRecado: varchar("telefone_recado", { length: 20 }),
    rua: text(),
    numero: varchar({ length: 20 }),
    bairro: varchar({ length: 100 }),
    cidade: varchar({ length: 100 }),
    uf: varchar({ length: 2 }),
    referencia: text(),
    condominio: text(),
    bloco: varchar({ length: 50 }),
    apartamento: varchar({ length: 50 }),
    createdAt: timestamp("created_at", { mode: 'string' }).default(sql `(now())`).notNull(),
    updatedAt: timestamp("updated_at", { mode: 'string' }).default(sql `(now())`).onUpdateNow().notNull(),
