    frete: decimal({ precision: 10, scale: 2 }).default('0.00').notNull(),
    montagem: decimal({ precision: 10, scale: 2 }).default('0.00').notNull(),
    lucro: decimal({ precision: 10, scale: 2 }).default('0.00').notNull(),
    comissao: decimal({ precision: 5, scale: 2 }).default('0.00').notNull(),
    jurosCartao: decimal("juros_cartao", { precision: 5, scale: 2 }).default('0.00').notNull(),
    valorVenda: decimal("valor_venda", { precision: 10, scale: 2 }).default('0.00').notNull(),
    prazoGarantia: int("prazo_garantia").default(90).notNull(),
